python3 -c $'import itertools as it,json,sys\nP=it.product;K=lambda x:x or sys.exit(\'FAIL\');A=\'qgre\'\ndef f(s,a):\n n,c=s\n if a==\'q\':return min(2,n+1),c\n if a==\'g\':return n,1\n if a==\'r\':return n,0\n return n-(n>0 and c),c\ndef g(s,a):\n m,c=s\n if a==\'q\':return min(3,2*m+1),c\n if a==\'g\':return m,1\n if a==\'r\':return m,0\n return (m//2 if c else m),c\nE=lambda s:(2**s[0]-1,s[1]);J=T=0\nfor s in P(range(3),range(2)):\n for a in A:K(E(f(s,a))==g(E(s),a));J+=1\n for seq in P(A,repeat=3):\n  x=s;y=E(s)\n  for a in seq:x=f(x,a);y=g(y,a);K(E(x)==y)\n  T+=1\nN={0,2};C=set(range(3));D=(\'reader\',\'friend\',\'researcher\');u={D[i] for i in N};v={D[i] for i in C}\nH=lambda n,c:(n<=c,bool(n),bool(c-n),c<=n)\nK(H(N,C)==H(u,v) and u=={\'reader\',\'researcher\'} and v==set(D))\nK(E(f((1,0),\'e\'))!=(E((1,0))[0]//2,0))\nK(H(N,C)!=H(u,v-{\'researcher\'}))\nR=[\'not_flagged\',\'uncertain\',\'possible\',\'observed\']\ndef V(r,t):return t.get(\'case\')==r[\'id\'] and t.get(\'provenance\')==r[\'source\'] and t.get(\'review\')==(r[\'risk\']!=\'not_flagged\')\nfor i,z in enumerate(R):\n r=dict(id=str(i),risk=z,source=\'reviewer\'+str(i));t=dict(case=str(i),review=z!=\'not_flagged\',provenance=r[\'source\']);K(V(r,t))\n if z==\'uncertain\':K(not V(r,{**t,\'review\':False}) and not V(r,{k:w for k,w in t.items() if k!=\'provenance\'}))\nprint(json.dumps(dict(version=\'G9\',research_domains=3,ai_transition_checks=J,ai_trace_checks=T,philosophy_formula_checks=4,welfare_record_checks=4,negative_controls=4,real_world_semantics_proved=False,human_or_ai_immortality_proved=False,divine_identity_proved=False,production_deployed=False),sort_keys=True))' "$@"
